class Solution {
    func characterReplacement(_ s: String, _ k: Int) -> Int {
        var arr = [Int](repeating: 0, count: 26)
        let chars = Array(s)
        let aValue = Int(Character("A").asciiValue!)

        var ans = 0
        var maxCount = 0
        var i = 0
        for j in 0..<chars.count {
            let idx = Int(chars[j].asciiValue!) - aValue
            arr[idx] += 1
            maxCount = max(maxCount, arr[idx])

            if j - i + 1 - maxCount > k {
                arr[Int(chars[i].asciiValue!) - aValue] -= 1
                i += 1
            }
            ans = max(ans, j - i + 1)
        }
        return ans
    }
}

